<?php

$n = (int)$argv[1];

function makeTree(int $depth): array
{
    if ($depth === 0) {
        return [null, null];
    }

    $childDepth = $depth - 1;
    return [
        makeTree($childDepth),
        makeTree($childDepth)
    ];
}

function checkTree(array $tree): int
{
    if ($tree[0] === null) {
        return 1;
    }

    return 1 + checkTree($tree[0]) + checkTree($tree[1]);
}

$stretchDepth = $n + 1;
$stretchTree = makeTree($stretchDepth);
$stretchCheck = checkTree($stretchTree);
printf("stretch tree of depth %d\t check: %d\n", $stretchDepth, $stretchCheck);
unset($stretchTree);

$longLivedTree = makeTree($n);

for ($depth = 4; $depth <= $n; $depth += 2) {
    $iterations = 1 << ($n - $depth + 4);
    $check = 0;

    for ($i = 0; $i < $iterations; $i++) {
        $tree = makeTree($depth);
        $check += checkTree($tree);
        unset($tree);
    }

    printf("%d\t trees of depth %d\t check: %d\n", $iterations, $depth, $check);
}

printf("long lived tree of depth %d\t check: %d\n", $n, checkTree($longLivedTree));
