$n = intval($argv[1]);

$masks = array_fill(0, $n + 1, 0);
for ($i = 1; $i <= $n; $i++) {
    $masks[$i] = (1 << (4 * $i)) - 1;
}

$perm = 0;
for ($i = 0; $i < $n; $i++) {
    $perm |= $i << (4 * $i);
}

$count = array_fill(0, $n, 0);
$r = $n;
$checksum = 0;
$maxFlips = 0;
$sign = 1;

while (true) {
    while ($r != 1) {
        $count[$r - 1] = $r;
        $r--;
    }

    $work = $perm;
    $flips = 0;

    while (($first = $work & 15) != 0) {
        $k = $first + 1;
        $mask = $masks[$k];
        $low = $work & $mask;
        $reversed = 0;

        for ($j = 0; $j < $k; $j++) {
            $reversed = ($reversed << 4) | ($low & 15);
            $low >>= 4;
        }

        $work = ($work & ~$mask) | $reversed;
        $flips++;
    }

    $checksum += $sign * $flips;
    if ($flips > $maxFlips) {
        $maxFlips = $flips;
    }
    $sign = -$sign;

    while (true) {
        if ($r == $n) {
            break 2;
        }

        $length = $r + 1;
        $mask = $masks[$length];
        $low = $perm & $mask;
        $first = $low & 15;

        $perm = ($perm & ~$mask)
              | (($low >> 4) | ($first << (4 * $r)));

        $count[$r]--;

        if ($count[$r] > 0) {
            break;
        }

        $r++;
    }
}

echo $checksum . PHP_EOL;
echo "Pfannkuchen(" . $n . ") = " . $maxFlips . PHP_EOL;
