$counts2 = array_fill(0, 16, 0);

for ($i = 0; $i < $length; $i++) {
    $a = $map[ord($sequence[$i])];

    if ($a < 0) {
        continue;
    }

    $counts1[$a]++;

    if ($i + 1 < $length) {
        $b = $map[ord($sequence[$i + 1])];

        if ($b >= 0) {
            $counts2[$a * 4 + $b]++;
        }
    }
}

